  ('master', 'bobur-qodirov', '{"id":"bobur-qodirov","name":"Bobur Qodirov","role":"Mikroskop va uchliklar bo‘yicha mutaxassis","city":"Toshkent","district":"Shayxontohur","years":10,"jobs":420,"rating":4.9,"reviews":182,"status":"online","cats":["handpiece","unit"],"tags":["Mikroskop","Uchlik/turbina","KaVo","NSK"],"brands":["KaVo","NSK","Carl Zeiss"],"photo":"/images/ustalar/usta-bobur.jpg","phone":"+998 90 456 78 90","telegram":"bobur_micro","reply":"~20 daqiqa","services":[{"name":"Mikroskop diagnostikasi","price":"300 000 so‘m","meta":"Kafolat: 3 oy"},{"name":"Uchlik ta’miri","price":"dan 250 000 so‘m","meta":"Javob vaqti: ~20 daqiqa"},{"name":"Profilaktika","price":"150 000 so‘m","meta":"Ish vaqti: 09:00–18:00"}]}'::jsonb, 3),
