insert into public.catalog_items (kind, id, payload, sort_at) values
  ('post', 'aziz-36', '{"id":"aziz-36","rank":1,"kind":"keys","topic":"endo","author":"Dr. Aziz Karimov","role":"Implantolog","place":"Toshkent","time":"3 soat oldin","avatar":"/images/bemorlar/bemor-aziz.jpg","title":"36-tish: surunkali apikal periodontit, qayta endodontik davolash","body":"Bemor 36-tishda og‘riq bilan murojaat qildi. Avvalgi davolash sifatsiz bo‘lgan. Mikroskop ostida qayta endodontik davolash o‘tkazildi.","tags":[{"t":"Klinik keys","tone":"keys"},{"t":"Endodontiya"},{"t":"Mikroskop"},{"t":"Qayta davolash"},{"t":"#Case","tone":"hash"}],"images":["/images/bemorlar/bemor-rvg.jpg","/images/bemorlar/bemor-opg.jpg","/images/bemorlar/bemor-kt.jpg","/images/bemorlar/bemor-intra.jpg","/images/seminars/teeth.jpg","/images/seminars/smile.jpg"],"likes":128,"comments":24,"shares":12,"thread":[{"name":"Dr. Jasur Murodov","text":"Mikroskop ostida ishlash to‘g‘ri qaror. MB2 kanal topildimi?"},{"name":"Dr. Malika Yusupova","text":"Qayta davolashdan keyin 6 oylik nazorat rentgenini ham ulashing."}]}'::jsonb, 0),
  ('post', 'malika-mta', '{"id":"malika-mta","rank":2,"kind":"keys","topic":"case","author":"Dr. Malika Yusupova","role":"Endodontist","place":"Samarqand","time":"5 soat oldin","avatar":"/images/bemorlar/bemor-malika.jpg","title":"MTA bilan apexifikatsiya: 11 yoshli bemor holati","body":"11 yoshli bemorda 21 tish travma sababli nekroz bo‘lgan. Apex ochiq. MTA bilan apexifikatsiya bajarildi. 6 oylik nazorat rentgenida ijobiy dinamika.","tags":[{"t":"Klinik keys","tone":"keys"},{"t":"Pediatriya"},{"t":"MTA"},{"t":"Apexifikatsiya"},{"t":"#Case","tone":"hash"}],"images":["/images/bemorlar/bemor-intra.jpg","/images/seminars/teeth.jpg","/images/bemorlar/bemor-opg.jpg","/images/bemorlar/bemor-rvg.jpg","/images/seminars/smile.jpg","/images/bemorlar/bemor-kt.jpg","/images/seminars/surgery.jpg"],"likes":96,"comments":18,"shares":9,"thread":[{"name":"Dr. Nilufar Tursunova","text":"Ochiq apeksda MTA qalinligi qancha qilindi?"}]}'::jsonb, 1),
  ('post', 'nilufar-savol', '{"id":"nilufar-savol","rank":3,"kind":"savol","topic":"orto","author":"Dr. Nilufar Tursunova","role":"Ortodont","place":"Toshkent","time":"1 kun oldin","avatar":"/images/bemorlar/bemor-dilnoza.jpg","title":"Mini-vint qayerga qo‘yilsa, intruziyada barqarorroq bo‘ladi?","body":"Yuqori jag‘ old guruhini intruziya qilishda mini-vint joylashuvi bo‘yicha tajribangiz qanday? Ikkala tomonda ham suyak hajmi cheklangan.","tags":[{"t":"Savol","tone":"savol"},{"t":"Ortodontiya"},{"t":"#MiniVint","tone":"hash"}],"images":["/images/seminars/smile.jpg","/images/seminars/teeth.jpg"],"likes":54,"comments":11,"shares":3,"thread":[]}'::jsonb, 2),
  ('post', 'jasur-talk', '{"id":"jasur-talk","rank":4,"kind":"muhokama","topic":"impl","author":"Dr. Jasur Murodov","role":"Jarroh","place":"Andijon","time":"2 kun oldin","avatar":"/images/bemorlar/bemor-bobur.jpg","title":"Peri-implantitda birinchi chora: konservativmi yoki jarrohlikmi?","body":"Chuqur cho‘ntak va suyak yo‘qolishi boshlangan implantda qanday protokolni birinchi tanlaysiz? Antibiotik, lazer yoki ochiq tozalash?","tags":[{"t":"Muhokama","tone":"talk"},{"t":"Implantologiya"},{"t":"#PeriImplantit","tone":"hash"}],"images":["/images/seminars/surgery.jpg","/images/bemorlar/bemor-kt.jpg","/images/bemorlar/bemor-opg.jpg"],"likes":73,"comments":16,"shares":6,"thread":[]}'::jsonb, 3),
  ('post', 'bekzod-paper', '{"id":"bekzod-paper","rank":5,"kind":"maqola","topic":"paro","author":"Dr. Bekzod Qodirov","role":"Parodontolog","place":"Buxoro","time":"4 kun oldin","avatar":"/images/bemorlar/bemor-anvar.jpg","title":"Parodontal cho‘ntakni yopishda emdogain va membrana: qisqa sharh","body":"So‘nggi kuzatuvlarda regenerativ material tanlovi natijani 12 oyda sezilarli o‘zgartirdi. Protokol va cheklovlarni muhokama qilamiz.","tags":[{"t":"Ilmiy maqola","tone":"paper"},{"t":"Parodontologiya"},{"t":"#Regeneratsiya","tone":"hash"}],"images":["/images/bemorlar/bemor-opg.jpg","/images/seminars/micro.jpg"],"likes":41,"comments":7,"shares":4,"thread":[]}'::jsonb, 4)
